#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Maibuk in-app Update signing key (docs/adr/0037). Re-runnable: it detects
# the secrets already on the repo and the pubkey already in tauri.conf.json.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

CONF="src-tauri/tauri.conf.json"
SECRET_KEY="TAURI_SIGNING_PRIVATE_KEY"
SECRET_PASS="TAURI_SIGNING_PRIVATE_KEY_PASSWORD"
REPO_ROOT=""
REPO=""
KEY_DIR=""
KEY_FILE=""
PUB_FILE=""
UPDATER_PASSWORD=""

# secret_exists NAME: true when the repo already has that Actions secret.
secret_exists() {
  gh secret list --json name -q '.[].name' 2>/dev/null | grep -qx "$1"
}

# read_password "Prompt" reads a hidden value into UPDATER_PASSWORD. Never echoed.
read_password() {
  printf '  %s%s%s ' "$BOLD" "$1" "$RESET"
  read -rs UPDATER_PASSWORD || { printf '\n'; warn "no input, stopping"; exit 1; }
  printf '\n'
}

# probe_password checks that UPDATER_PASSWORD opens KEY_FILE by signing a
# throwaway file. The password goes through the environment, not argv.
probe_password() {
  local probe="$KEY_DIR/probe.txt" ok=0
  printf 'maibuk updater key check\n' > "$probe"
  if TAURI_SIGNING_PRIVATE_KEY_PASSWORD="$UPDATER_PASSWORD" \
     pnpm tauri signer sign -f "$KEY_FILE" "$probe" >/dev/null 2>&1; then
    ok=1
  fi
  rm -f "$probe" "$probe.sig"
  (( ok ))
}

run_wizard() {

TOTAL_STAGES=7

banner "Maibuk updater key setup"

# ── 1. Preflight ─────────────────────────────────────────────────────────
stage "Preflight"
for tool in pnpm node gh; do
  command -v "$tool" >/dev/null 2>&1 || { warn "$tool is not on PATH; install it and re-run"; exit 1; }
done
gh auth status >/dev/null 2>&1 || { warn "gh is not logged in; run 'gh auth login' and re-run"; exit 1; }
REPO_ROOT=$(git rev-parse --show-toplevel 2>/dev/null) || { warn "not inside a git repo"; exit 1; }
[[ -f "$REPO_ROOT/$CONF" ]] || { warn "$CONF not found under $REPO_ROOT; run this from the Maibuk repo"; exit 1; }
cd "$REPO_ROOT"
REPO=$(gh repo view --json nameWithOwner -q .nameWithOwner)
step "Repo: $REPO"
step "Checkout: $REPO_ROOT ($(git rev-parse --abbrev-ref HEAD))"
pause "Checks passed. Press Enter to continue"

# ── 2. Warning and rotation guard ────────────────────────────────────────
stage "Warning: the signing key is the Update trust root"
if secret_exists "$SECRET_KEY" && secret_exists "$SECRET_PASS"; then
  warn "The signing key secrets already exist on $REPO."
  warn "A new key replaces them. Installs built with the old key can no longer Update."
  confirm "Rotate the key anyway?" || { say "Nothing changed."; exit 0; }
fi
warn "Losing the private key or its password ends in-app Update for every existing install."
warn "Those installs must reinstall by hand from the Download Page (ADR 0037)."
say "The private key goes into the GitHub secret $SECRET_KEY, and the password into"
say "$SECRET_PASS. Both must also live in your password manager."
printf '  Type %sI understand%s to continue: ' "$BOLD" "$RESET"
reply=""
read -r reply || { warn "no input, stopping"; exit 1; }
[[ "$reply" == "I understand" ]] || { say "Not confirmed. Nothing changed."; exit 1; }

# ── 3. Generate the keypair in a private temp dir ────────────────────────
stage "Generate the signing keypair"
KEY_DIR=$(mktemp -d)
chmod 700 "$KEY_DIR"
case "$KEY_DIR" in
  "$REPO_ROOT"|"$REPO_ROOT"/*) warn "temp dir landed inside the repo; refusing"; exit 1 ;;
esac
KEY_FILE="$KEY_DIR/maibuk-updater.key"
PUB_FILE="$KEY_FILE.pub"
step "Keys are written to $KEY_DIR (outside the repo, mode 700)."
step "Tauri now asks for a password. Choose a long one and type it carefully;"
step "stage 4 asks for it again and checks it against the key."
pnpm tauri signer generate -w "$KEY_FILE"
[[ -s "$KEY_FILE" && -s "$PUB_FILE" ]] || { warn "expected $KEY_FILE and $PUB_FILE; generate did not write both"; exit 1; }
chmod 600 "$KEY_FILE" "$PUB_FILE"
printf '  %s✓ generated%s %s and %s\n' "$GREEN" "$RESET" "$KEY_FILE" "$PUB_FILE"
pause "Press Enter to continue"

# ── 4. Store the secrets on GitHub ───────────────────────────────────────
stage "Store the signing key and password as GitHub secrets"
say "The password is checked against the key before anything is stored."
attempt=0
while :; do
  attempt=$((attempt + 1))
  read_password "Password for the new key (hidden):"
  if [[ -z "$UPDATER_PASSWORD" ]]; then
    warn "empty. Type the password you gave the generate step."
  elif probe_password; then
    break
  else
    warn "that password does not open the key."
  fi
  if (( attempt >= 3 )); then
    UPDATER_PASSWORD=""
    warn "three tries failed. Keys are still in $KEY_DIR; re-run the wizard."
    exit 1
  fi
done
step "Password verified against the key."
gh secret set "$SECRET_KEY" < "$KEY_FILE"
printf '%s' "$UPDATER_PASSWORD" | gh secret set "$SECRET_PASS"
UPDATER_PASSWORD=""
WRITTEN_SECRET+=("$SECRET_KEY" "$SECRET_PASS")
printf '  %s✓ set%s GitHub secrets %s and %s on %s\n' "$GREEN" "$RESET" "$SECRET_KEY" "$SECRET_PASS" "$REPO"
pause "Press Enter to continue"

# ── 5. Save the key and password off the machine ─────────────────────────
stage "Save the key and password in your password manager"
warn "Do this now. If the private key or its password is lost, no existing install can ever Update again."
step "Private key file: $KEY_FILE"
step "Open it and copy the full contents into your password manager, as a secure note or attachment."
step "Save the password you typed in stage 4 in the same entry."
say "Nothing else on disk holds the password."
reply=""
while :; do
  printf '  Type %ssaved%s once both are in your password manager: ' "$BOLD" "$RESET"
  read -r reply || { warn "no input, stopping; the key stays in $KEY_DIR"; exit 1; }
  [[ "$reply" == "saved" ]] && break
  say "Not yet. Type exactly: saved"
done

# ── 6. Point the app at the new public key ───────────────────────────────
stage "Update the updater public key in $CONF"
RAW=$(cat "$PUB_FILE")
if [[ "$RAW" == "untrusted comment:"* ]]; then
  # Raw minisign text: tauri.conf.json carries it base64-encoded.
  PUB=$(printf '%s\n' "$RAW" | base64 | tr -d '\n')
else
  PUB=$(printf '%s' "$RAW" | tr -d '\n')
fi
DECODED=$(printf '%s' "$PUB" | base64 -d 2>/dev/null || true)
[[ "$DECODED" == "untrusted comment: minisign public key"* ]] || { warn "$PUB_FILE is not a minisign public key; stopping"; exit 1; }

CURRENT=$(node -e 'const fs=require("fs");process.stdout.write(JSON.parse(fs.readFileSync(process.argv[1],"utf8")).plugins.updater.pubkey)' "$CONF")
if [[ "$CURRENT" == "$PUB" ]]; then
  step "$CONF already carries this public key; nothing to change."
else
  # Replace only the pubkey value so the rest of the file keeps its formatting.
  node -e '
    const fs = require("fs");
    const [file, pub] = process.argv.slice(1);
    const src = fs.readFileSync(file, "utf8");
    JSON.parse(src);
    const re = /"pubkey"\s*:\s*"[^"]*"/g;
    const hits = src.match(re) || [];
    if (hits.length !== 1) { console.error("expected one pubkey in " + file + ", found " + hits.length); process.exit(1); }
    const next = src.replace(re, "\"pubkey\": \"" + pub + "\"");
    if (JSON.parse(next).plugins.updater.pubkey !== pub) { console.error("pubkey did not round-trip"); process.exit(1); }
    fs.writeFileSync(file, next);
  ' "$CONF" "$PUB"
  step "Updated $CONF. The diff:"
  git --no-pager diff -- "$CONF"
fi
pause "Press Enter to continue"

# ── 7. Clean up the temp dir, then next steps ────────────────────────────
stage "Clean up and next steps"
if confirm "Delete the temp key files in $KEY_DIR now? Only if the key is saved in your password manager"; then
  rm -f "$KEY_FILE" "$PUB_FILE"
  rmdir "$KEY_DIR"
  printf '  %s✓ deleted%s %s\n' "$GREEN" "$RESET" "$KEY_DIR"
else
  warn "kept $KEY_DIR. Delete it yourself later: rm -f $KEY_FILE $PUB_FILE && rmdir $KEY_DIR"
fi
say "Next, yours to run:"
step "Commit only $CONF on the branch you ran this on (the Update task branch), not on a new branch off main: until Update merges, main has no plugins.updater block for the key."
step "Release builds: the two secrets are set, so the release workflow signs with them. Nothing else to do."
step "Local signed builds: export both before pnpm tauri build, from the password manager:"
note "    export TAURI_SIGNING_PRIVATE_KEY=\"\$(cat /path/to/saved/key)\""
note "    export TAURI_SIGNING_PRIVATE_KEY_PASSWORD='<password>'"
UPDATER_PASSWORD=""
# ──────────────────────────────────────────────────────────────────────────

finish
}

run_wizard "$@"; exit
